  sl=b['sl'];z=x[sl]-b['step']*grad[sl];domain=b['domain'];projected=z.copy()
  if domain=='positive':projected=np.maximum(z,0)
  elif domain=='box':projected=np.clip(z,-radius,radius)
  elif domain=='ball':projected=z*min(1.,radius/max(np.linalg.norm(z),1e-300))
  res[sl]=x[sl]-projected
