  sl=b['sl'];n=sl.stop-sl.start;domain=b['domain'];r=m.radius(b,bound_state);radii.append(r);E=m.E[sl]
  if domain=='free':continue
  if domain=='positive':rows.append(-E);rhs.append(np.zeros(n));cones.append(clarabel.NonnegativeConeT(n))
  elif r==0:rows.append(E);rhs.append(np.zeros(n));cones.append(clarabel.ZeroConeT(n))
  elif domain=='box':rows.append(np.r_[E,-E]);rhs.append(np.full(2*n,r));cones.append(clarabel.NonnegativeConeT(2*n))
  elif domain=='ball':rows.append(np.r_[np.zeros((1,m.offset)),-E]);rhs.append(np.r_[r,np.zeros(n)]);cones.append(clarabel.SecondOrderConeT(n+1))
