 records.append(record);states.append(x);(p/'structured-iterations.json').write_text(json.dumps(records,indent=2));print(json.dumps(record),flush=True)
 if str(solution.status) not in ['Solved','AlmostSolved']:raise InnerFailure(str(solution.status))
