except (NoConvergence,Budget,InnerFailure) as e:termination=type(e).__name__+(': '+str(e) if not isinstance(e,NoConvergence) else '')
assert states
best=min(range(len(states)),key=lambda i:records[i]['actual_relative_natural_residual']);x=states[best];grad=m.gradient_primal(x);dense=m.H@x+m.g;agreement=float(np.max(abs(grad-dense)/(1+np.maximum(abs(grad),abs(dense)))));natural=float(np.max(abs(m.residual(x))/(1+abs(x))));sweep,_=m.sweep(x);feas=[]
for b in m.blocks:
