import model as m
import numpy as np,json
jblocks={};cblocks={}
for b in m.blocks:
 label=b['label']
 if label[0]=='joint':jblocks.setdefault(label[1],[]).append(b)
 else:cblocks.setdefault(json.dumps(label[1]),[]).append(b)
ops=[];joint_order=[j for component in m.d['joint_order']['components'] for j in component['joints']];joints={j['identity']:j for j in m.d['joints']};contacts={json.dumps(c['identity']):c for c in m.d['contacts']}
