  key=json.dumps(identity);c=contacts[key];bs=cblocks[key];normals=[b for b in bs if b['label'][2]=='normal'];order=list(range(len(normals)))
  if len(order)==4:
   ra=[m.v(cp['ra'])[:3] for cp in c['points']];other=max(range(1,4),key=lambda k:float(np.sum((ra[k]-ra[0])**2)));order=[0,other,*[k for k in range(1,4) if k!=other]]
  index=0
  while index<len(order):
   a=normals[order[index]]
   if index+1<len(order):
    b=normals[order[index+1]];J=np.r_[a['J'],b['J']];K=J@m.M@J.T
    if np.linalg.det(K)>1e-5*K[0,0]*K[1,1]:
     indices=np.array([a['sl'].start,b['sl'].start]);ops.append(dict(label=['contact',identity,'normal_pair',order[index:index+2]],J=J,K=K,G=np.zeros((2,2)),indices=indices,bias=np.r_[a['bias'],b['bias']],domain='positive_pair'));index+=2;continue
   ops.append(a);index+=1
  by_name={b['label'][2]:b for b in bs if b['label'][2]!='normal'}
  names=['rolling','twist','tangent'] if m.f(c['prepared_softness'][3])==1 and color!=23 else ['twist','rolling','tangent']
  ops.extend(by_name[name] for name in names if name in by_name)
for b in ops:
 if 'indices' not in b:b['indices']=np.arange(b['sl'].start,b['sl'].stop)
 b['B']=m.M@b['J'].T;b['inverse']=np.linalg.inv(b['K']+b['G'])
seen=np.concatenate([b['indices'] for b in ops]);assert sorted(seen)==list(range(m.offset))

def project(x):
 x=x.copy()
 # Normal and limit feasibility before contact radii are evaluated.
 for b in m.blocks:
  if b['domain']=='positive':x[b['sl']]=np.maximum(x[b['sl']],0)
 for b in m.blocks:
  if b['domain']=='box':x[b['sl']]=np.clip(x[b['sl']],-m.radius(b,x),m.radius(b,x))
  elif b['domain']=='ball':
   y=x[b['sl']];x[b['sl']]=y*min(1.,m.radius(b,x)/max(np.linalg.norm(y),1e-300))
