  x=np.zeros(2)
  if active:x[active]=-np.linalg.solve(K[np.ix_(active,active)],q[active])
  w=K@x+q
  if min(x)>=-1e-12 and all(w[k]>=-1e-12 for k in range(2) if k not in active):return np.maximum(x,0)
