  elif b['domain']=='positive_pair':new=solve_pair(K,grad-K@before)
  elif b['domain']=='box':new=np.clip(new,-m.radius(b,x),m.radius(b,x))
  elif b['domain']=='ball':new=m.metric_project(K,grad-K@before,m.radius(b,x))
  next_v=velocity+b['B']@(new-before);vchange=float(np.max(abs(next_v-velocity)/(1+np.maximum(abs(next_v),abs(velocity)))));ichange=float(np.max(abs(new-before)/(1+np.maximum(abs(new),abs(before)))))
  if vchange>max_v:worst=b['label']
  max_v=max(max_v,vchange);max_i=max(max_i,ichange);x[indices]=new;velocity=next_v
